import{Tippy}from"../../public/js/lib/tippy.min.js";document.addEventListener("DOMContentLoaded",function(e){(new WOW).init();let t=document.querySelectorAll(".buttonRefreshPagina");t.forEach(e=>{$(e).click(function(e){e.preventDefault(),location.reload()})});let a=new Tippy,n=[{label:".buttonRefreshTable",obj:{content:"Recargar la tabla",animation:"scale",placement:"top"}},{label:".buttonRefreshPagina",obj:{content:"Recargar la página",animation:"scale",placement:"top"}},{label:".buttonPaginaWeb",obj:{content:"Visitar sitio web",animation:"scale",placement:"top"}},{label:".sucursal_session",obj:{content:`${$("#cod_sucursal_sesion").val()} | ${$("#descripcion_sesion").val()} | ${$("#tipo_sesion").val()} `,animation:"scale",placement:"bottom"}},{label:".infoEmailPass",obj:{content:"En caso desea trabajar con el envío de correos electrónicos, debe rellenar correctamente este campo.",animation:"scale",placement:"top"}}];for(let e=0;e<n.length;e++)a.init(n[e].label,n[e].obj);$(document).on("select2:open",()=>{document.querySelector(".select2-search__field").focus()});let o=document.querySelectorAll(".needs-validation");Array.prototype.slice.call(o).forEach(function(e){e.addEventListener("submit",function(t){e.checkValidity()||(t.preventDefault(),t.stopPropagation()),e.classList.add("was-validated")},!1)})});